import * as ImageManipulator from 'expo-image-manipulator';
import * as FileSystem from 'expo-file-system';
import * as ort from 'onnxruntime-react-native';
import jpeg from 'jpeg-js';

export async function preprocessImage(uri: string) {
  const resized = await ImageManipulator.manipulateAsync(
    uri,
    [{ resize: { width: 224, height: 224 } }],
    {
      compress: 1,
      format: ImageManipulator.SaveFormat.JPEG,
      base64: true
    }
  );

  if (!resized.base64) {
    throw new Error('Base64 conversion failed');
  }

  const buffer = Buffer.from(resized.base64, 'base64');
  const decoded = jpeg.decode(buffer, { useTArray: true });

  const { width, height, data } = decoded;
  const float32Data = new Float32Array(3 * width * height);

  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const idx = (y * width + x) * 4;
      const pixelIndex = y * width + x;

      const r = data[idx] / 255.0;
      const g = data[idx + 1] / 255.0;
      const b = data[idx + 2] / 255.0;

      float32Data[pixelIndex] = r;
      float32Data[pixelIndex + width * height] = g;
      float32Data[pixelIndex + 2 * width * height] = b;
    }
  }

  return new ort.Tensor('float32', float32Data, [1, 3, height, width]);
}

