import * as SQLite from 'expo-sqlite';

const db = SQLite.openDatabaseSync('mediscan.db');

export function initializeDatabase() {
  db.execSync(`
    CREATE TABLE IF NOT EXISTS screening_results (
      id TEXT PRIMARY KEY NOT NULL,
      condition_name TEXT NOT NULL,
      confidence REAL NOT NULL,
      recommendation TEXT NOT NULL,
      created_at TEXT NOT NULL
    );
  `);
}

export function saveScreeningResult(data: {
  id: string;
  condition_name: string;
  confidence: number;
  recommendation: string;
}) {
  db.runSync(
    `
      INSERT INTO screening_results (
        id, condition_name, confidence, recommendation, created_at
      ) VALUES (?, ?, ?, ?, ?)
    `,
    [data.id, data.condition_name, data.confidence, data.recommendation, new Date().toISOString()]
  );
}

export function getHistory() {
  return db.getAllSync(`SELECT * FROM screening_results ORDER BY created_at DESC`);
}

