LOW_CONFIDENCE_THRESHOLD = 0.60
URGENT_CLASSES = {"suspicious_mole", "corneal_opacity"}

def apply_clinical_logic(prediction, confidence):
    if confidence < LOW_CONFIDENCE_THRESHOLD:
        return {
            "status": "abstain",
            "message": "Inconclusive result. Professional review recommended."
        }

    if prediction in URGENT_CLASSES:
        return {
            "status": "urgent_referral",
            "message": "Urgent medical referral recommended."
        }

    return {
        "status": "standard",
        "message": "Follow standard clinical guidance."
    }

